import React, { useState } from 'react';
import { 
  Card, 
  Table, 
  Tag, 
  Typography, 
  Space,
  Alert,
  Input,
  Select,
  Button,
  Row,
  Col,
  Statistic
} from 'antd';
import { 
  FileTextOutlined,
  FilterOutlined,
  DownloadOutlined,
  TrophyOutlined,
  DollarOutlined,
  BarChartOutlined
} from '@ant-design/icons';
import { useQuery } from 'react-query';
import dayjs from 'dayjs';
import axios from 'axios';

const { Title, Text } = Typography;
const { Search } = Input;
const { Option } = Select;

const Summary = () => {
  const [filters, setFilters] = useState({
    date: '',
    level: '',
    minProbability: '',
    team: ''
  });

  // Query para obtener resumen de análisis con filtros
  const {
    data: analysisData,
    isLoading,
    error,
    refetch
  } = useQuery(
    ['summary', filters],
    async () => {
      const params = new URLSearchParams();
      if (filters.date) params.append('date', filters.date);
      if (filters.level) params.append('level', filters.level);
      if (filters.minProbability) params.append('minProbability', filters.minProbability);
      if (filters.team) params.append('team', filters.team);
      
      const response = await axios.get(`/api/games/summary?${params.toString()}`);
      return response.data;
    },
    {
      retry: 1,
    }
  );

  const handleFilterChange = (key, value) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  };

  const handleSearch = () => {
    refetch();
  };

  const handleExport = () => {
    // Función para exportar datos (implementar después)
    console.log('Exportar datos...');
  };

  // Configuración de columnas para la tabla
  const columns = [
    {
      title: 'Fecha',
      dataIndex: 'game_date',
      key: 'game_date',
      width: 120,
      render: (date) => dayjs(date).format('DD/MM/YYYY'),
      sorter: (a, b) => dayjs(a.game_date).unix() - dayjs(b.game_date).unix(),
    },
    {
      title: 'Hora',
      dataIndex: 'game_time',
      key: 'game_time',
      width: 100,
      render: (time) => time ? dayjs(`2000-01-01 ${time}`).format('HH:mm') : '-',
    },
    {
      title: 'Partido',
      key: 'matchup',
      render: (_, record) => (
        <div>
          <Text strong>{record.home_team_name}</Text>
          <br />
          <Text type="secondary">vs</Text>
          <br />
          <Text strong>{record.away_team_name}</Text>
        </div>
      ),
      filters: [
        { text: 'Local', value: 'home' },
        { text: 'Visitante', value: 'away' },
      ],
      onFilter: (value, record) => {
        if (value === 'home') return record.home_probability > record.away_probability;
        if (value === 'away') return record.away_probability > record.home_probability;
        return true;
      },
    },
    {
      title: 'Probabilidad Local',
      dataIndex: 'home_probability',
      key: 'home_probability',
      width: 140,
      render: (prob) => (
        <Text strong style={{ color: prob > 60 ? '#52c41a' : prob > 50 ? '#faad14' : '#ff4d4f' }}>
          {prob.toFixed(1)}%
        </Text>
      ),
      sorter: (a, b) => a.home_probability - b.home_probability,
    },
    {
      title: 'Probabilidad Visitante',
      dataIndex: 'away_probability',
      key: 'away_probability',
      width: 140,
      render: (prob) => (
        <Text strong style={{ color: prob > 60 ? '#52c41a' : prob > 50 ? '#faad14' : '#ff4d4f' }}>
          {prob.toFixed(1)}%
        </Text>
      ),
      sorter: (a, b) => a.away_probability - b.away_probability,
    },
    {
      title: 'Línea Justa Local',
      dataIndex: 'home_american_odds',
      key: 'home_american_odds',
      width: 140,
      render: (odds) => (
        <Text style={{ color: odds > 0 ? '#52c41a' : '#ff4d4f' }}>
          {odds > 0 ? '+' : ''}{odds}
        </Text>
      ),
    },
    {
      title: 'Línea Justa Visitante',
      dataIndex: 'away_american_odds',
      key: 'away_american_odds',
      width: 140,
      render: (odds) => (
        <Text style={{ color: odds > 0 ? '#52c41a' : '#ff4d4f' }}>
          {odds > 0 ? '+' : ''}{odds}
        </Text>
      ),
    },
    {
      title: 'Nivel',
      dataIndex: 'level',
      key: 'level',
      width: 120,
      render: (level) => {
        const levelConfig = {
          diamond: { color: '#f5222d', text: 'Diamante', icon: <TrophyOutlined /> },
          exclusive: { color: '#fa8c16', text: 'Exclusivo', icon: <DollarOutlined /> },
          vip: { color: '#1890ff', text: 'VIP', icon: <BarChartOutlined /> },
        };
        const config = levelConfig[level] || { color: 'default', text: level };
        return (
          <Tag color={config.color} icon={config.icon}>
            {config.text}
          </Tag>
        );
      },
      filters: [
        { text: 'Diamante', value: 'diamond' },
        { text: 'Exclusivo', value: 'exclusive' },
        { text: 'VIP', value: 'vip' },
      ],
      onFilter: (value, record) => record.level === value,
    },
  ];

  const analysis = analysisData?.data || [];

  // Estadísticas
  const stats = {
    total: analysis.length,
    diamond: analysis.filter(a => a.level === 'diamond').length,
    exclusive: analysis.filter(a => a.level === 'exclusive').length,
    vip: analysis.filter(a => a.level === 'vip').length,
    avgHomeProb: analysis.length > 0 ? 
      (analysis.reduce((sum, a) => sum + a.home_probability, 0) / analysis.length).toFixed(1) : 0,
    avgAwayProb: analysis.length > 0 ? 
      (analysis.reduce((sum, a) => sum + a.away_probability, 0) / analysis.length).toFixed(1) : 0,
  };

  return (
    <div className="summary-page">
      <Card>
        <div style={{ marginBottom: 16 }}>
          <Title level={2}>
            <FileTextOutlined /> Resumen de Análisis
          </Title>
          <Text type="secondary">
            Vista completa de análisis con filtros avanzados
          </Text>
        </div>

        {/* Filtros */}
        <Card size="small" style={{ marginBottom: 16 }}>
          <Row gutter={16} align="middle">
            <Col xs={24} sm={12} md={6}>
              <Text strong>Fecha:</Text>
              <Input
                placeholder="YYYY-MM-DD"
                value={filters.date}
                onChange={(e) => handleFilterChange('date', e.target.value)}
                style={{ marginTop: 4 }}
              />
            </Col>
            <Col xs={24} sm={12} md={6}>
              <Text strong>Nivel:</Text>
              <Select
                placeholder="Seleccionar nivel"
                value={filters.level}
                onChange={(value) => handleFilterChange('level', value)}
                style={{ width: '100%', marginTop: 4 }}
                allowClear
              >
                <Option value="diamond">Diamante</Option>
                <Option value="exclusive">Exclusivo</Option>
                <Option value="vip">VIP</Option>
              </Select>
            </Col>
            <Col xs={24} sm={12} md={6}>
              <Text strong>Prob. Mínima:</Text>
              <Input
                placeholder="Ej: 60"
                value={filters.minProbability}
                onChange={(e) => handleFilterChange('minProbability', e.target.value)}
                style={{ marginTop: 4 }}
              />
            </Col>
            <Col xs={24} sm={12} md={6}>
              <Text strong>Equipo:</Text>
              <Search
                placeholder="Buscar equipo"
                value={filters.team}
                onChange={(e) => handleFilterChange('team', e.target.value)}
                style={{ marginTop: 4 }}
              />
            </Col>
          </Row>
          <Row style={{ marginTop: 16 }}>
            <Col>
              <Space>
                <Button
                  type="primary"
                  icon={<FilterOutlined />}
                  onClick={handleSearch}
                  loading={isLoading}
                >
                  Aplicar Filtros
                </Button>
                <Button
                  icon={<DownloadOutlined />}
                  onClick={handleExport}
                >
                  Exportar
                </Button>
              </Space>
            </Col>
          </Row>
        </Card>

        {/* Estadísticas */}
        <Row gutter={16} style={{ marginBottom: 16 }}>
          <Col xs={12} sm={6}>
            <Statistic
              title="Total Análisis"
              value={stats.total}
              prefix={<FileTextOutlined />}
            />
          </Col>
          <Col xs={12} sm={6}>
            <Statistic
              title="Diamante"
              value={stats.diamond}
              prefix={<TrophyOutlined />}
              valueStyle={{ color: '#f5222d' }}
            />
          </Col>
          <Col xs={12} sm={6}>
            <Statistic
              title="Exclusivo"
              value={stats.exclusive}
              prefix={<DollarOutlined />}
              valueStyle={{ color: '#fa8c16' }}
            />
          </Col>
          <Col xs={12} sm={6}>
            <Statistic
              title="VIP"
              value={stats.vip}
              prefix={<BarChartOutlined />}
              valueStyle={{ color: '#1890ff' }}
            />
          </Col>
        </Row>

        {error && (
          <Alert
            message="Error"
            description={error.message}
            type="error"
            showIcon
            style={{ marginBottom: 16 }}
          />
        )}

        {isLoading ? (
          <div style={{ textAlign: 'center', padding: '50px' }}>
            <Text>Cargando análisis...</Text>
          </div>
        ) : (
          <>
            {analysis.length === 0 ? (
              <Alert
                message="No hay análisis"
                description="No se encontraron análisis con los filtros aplicados."
                type="info"
                showIcon
              />
            ) : (
              <Table
                columns={columns}
                dataSource={analysis}
                rowKey="id"
                pagination={{
                  pageSize: 15,
                  showSizeChanger: true,
                  showQuickJumper: true,
                  showTotal: (total, range) => 
                    `${range[0]}-${range[1]} de ${total} análisis`,
                }}
                size="middle"
                scroll={{ x: 1200 }}
              />
            )}
          </>
        )}
      </Card>
    </div>
  );
};

export default Summary;
